L9_1.m_Talk_SCN = "\229\188\130\229\184\184\228\190\181\232\154\128\231\142\176\232\177\161\229\143\145\231\148\159\228\185\139\229\144\142\239\188\140\229\176\177\229\156\168\229\135\160\228\184\170\229\176\143\230\151\182\229\137\141\239\188\140\229\186\147\229\141\154\229\176\143\229\167\144\233\128\154\232\191\135\229\164\150\228\186\164\233\131\168\233\151\168\239\188\140\229\184\140\230\156\155\230\136\145\228\187\172\229\184\174\229\191\153\230\144\156\231\180\162\231\137\185\229\174\154\229\188\130\229\184\184\231\142\176\232\177\161\231\154\132\228\186\139\228\187\182\232\174\176\229\189\149\227\128\130"
L9_1.m_Talk_DEU = "Vor einigen Stunden, unmittelbar nach Beginn des Counterside-Effekts, erfuhren wir \195\188ber diplomatische Kan\195\164le, dass Miss Cooper die Suche nach gewissen \195\188bernat\195\188rlichen Vorf\195\164llen veranlasst hat."
